Mix = tuple[int, int, int, int]  # lk, pr, lb, srs
TALK: Mix = (50, 40, 0, 10)
PRACTICE: Mix = (30, 60, 0, 10)
HANDS_ON: Mix = (20, 70, 0, 10)
LAB: Mix = (20, 30, 40, 10)
SCHOOL: Mix = (40, 60, 0, 0)
SCHOOL_PRACTICE: Mix = (20, 80, 0, 0)
SRS: Mix = (0, 0, 0, 100)


def C(key: str, title: str, tf: tuple[str, ...] = (), activity: str = "") -> dict:
    return {"key": key, "activity": activity, "title": title, "tf_ids": list(tf)}


def LO(key: str, comp: str, kind: str, text: str) -> dict:
    return {"key": key, "competency_key": comp, "kind": kind, "text": text, "tf_id": None}


def T(
    key: str, title: str, weight: int, mix: Mix, los: tuple[str, ...], tags: tuple[str, ...], control: str
) -> dict:
    lk, pr, lb, srs = mix
    return {
        "key": key,
        "title": title,
        "weight": weight,
        "mix": {"lk": lk, "pr": pr, "lb": lb, "srs": srs},
        "lo_keys": list(los),
        "tags": list(tags),
        "control_form": control,
    }


def M(
    key: str, title: str, weight: int, topics: list[dict], control: str | None = None, kind: str = "regular"
) -> dict:
    return {
        "key": key,
        "title": title,
        "weight": weight,
        "kind": kind,
        "control_form": control,
        "topics": topics,
    }


def kun(comp: str, prefix: str, know: str, can: str, master: str) -> list[dict]:
    return [
        LO(f"{prefix}1", comp, "know", know),
        LO(f"{prefix}2", comp, "can", can),
        LO(f"{prefix}3", comp, "master", master),
    ]


def skeleton(
    goal: str, tasks: list[str], comps: list[dict], outcomes: list[dict], modules: list[dict], **extra: str
) -> dict:
    """Результаты обучения вкладываются в свои компетенции (так их отдаёт модель по схеме SkeletonDraft)."""
    nested = [
        {
            **comp,
            "outcomes": [
                {k: v for k, v in o.items() if k != "competency_key"}
                for o in outcomes
                if o["competency_key"] == comp["key"]
            ],
        }
        for comp in comps
    ]
    data = {
        "goal": goal,
        "tasks": tasks,
        "direction": extra.get("direction"),
        "level": extra.get("level"),
        "competencies": nested,
        "modules": modules,
    }
    SkeletonDraft.model_validate(data)
    return data


