FIXTURES = {
    OPEN[1]["request"]: Q1,
    OPEN[2]["request"]: Q2,
    OPEN[3]["request"]: Q3,
    OPEN[4]["request"]: Q4,
    OPEN[5]["request"]: Q5,
    OWN["med_security"]: MED,
    OWN["arduino_kids"]: ARDUINO,
    OWN["accounting_1c"]: ACCOUNTING,
    OWN["sql_economists"]: SQL_ECON,
    OWN["sales_ai"]: SALES,
}


def main() -> None:
    FOLDER.mkdir(parents=True, exist_ok=True)
    (FOLDER / "default.json").write_text(
        json.dumps(
            {"_note": "нейтральный каркас для запросов без своей фикстуры", **DEFAULT},
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    for text, data in FIXTURES.items():
        path = FOLDER / f"{request_key(text)}.json"
        path.write_text(
            json.dumps({"_request": text, **data}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        print(path.relative_to(ROOT), "—", text[:60])


if __name__ == "__main__":
    main()
